WITH k(key) AS (VALUES ('آت الخاصة والأفراد والمنظمات الدولية بها'),('أو أحد أعضاء مجلس مديريها أو من في حكمهم'),('إسلامية أو النظام العام أو الآداب العامة'),('إلغاء عضوية المخالف لدى الهيئة'),('ئة نظام العمل ونظام التأمينات الاجتماعية'),('ئيس مجلس إدارة صندوق التنمية الوطني بذلك'),('ئيس يسمى بأمر من رئيس مجلس الوزراء رئيسا'),('ا مجلس الإدارة وفقا للأحكام المنظمة لذلك'),('ا من اعتمادات في الميزانية العامة للدولة'),('ا وزير الداخلية بالاتفاق مع وزير المالية'),('ا يقرره المجلس بحسب الصلاحيات المخولة له'),('ات والدورات التدريبية التي تنفذها الهيئة'),('اج نفسي أو برامج تأهيلية بما يلائم حالته'),('ازفة بعبور الأودية والشعاب أثناء جريانها'),('الإقليمية والدولية ذات الصلة باختصاصاته'),('التي لدى الجهات التي ترغب في التخلص منها'),('الثقافية المنشأة بقرار مجلس الوزراء رقم'),('العامة للدولة ويصرف منها بقرار من الرئيس'),('القضاة على الإنهاءات إذا كانت فيها خصومة'),('اللائحة المالية للنشاطات الثقافية'),('اللوائح الأخرى بالاتفاق مع وزارة المالية'),('المحافظ ونائبا المحافظ وموظفو البنك'),('المحامين الممارسين وفق أحكام هذا النظام'),('المملكة من السلع والخدمات وإعادة التصدير'),('الموافقة على الحسابات الختامية للهيئة'),('الميزانية السنوية المعتمدة ولوائح الهيئة'),('الهيئة السعودية للمراجعين الداخليين'),('ام نظام العمل ونظام التأمينات الاجتماعية'),('ام وتقرير العقوبة المناسبة في حق المخالف'),('امة منشآت ومرافق ممارسة الأنشطة الرياضية'),('ان من القطاع الخاص ذوعلاقة بنشاط التصدير'),('بأغلبية أصوات أعضائها الحاضرين على الأقل'),('بالاتفاق مع صندوق التنمية الوطني'),('ة الاعتبارية وبالاستقلال المالي والإداري'),('ة بمن تراه لتأدية المهمات الموكولة إليها'),('ة خمس سنوات تبدأ من تاريخ اعتماد الآليات'),('تحقيق أغراض الهيئة في حدود أحكام التنظيم'),('تحقيق مستهدفات الاستثمار من جميع مصادرها'),('تطلبات النظامية للمقطورة أو نصف المقطورة'),('تعقد الجلسات بحضور ثلثي الأعضاء'),('تغيير في المحتوى أو تاريخ نشر الإحصاءات'),('تقدمها وفقا للأنظمة ذات الصلة باختصاصها'),('تمدها المجلس مدينة صناعية أو منطقة تقنية'),('تنظيميا بمجلس الشؤون الاقتصادية والتنمية'),('ثلي الجهات الحكومية والجهات غير الحكومية'),('جلس إدارة صندوق التنمية الوطني لاعتمادها'),('حقيق الأهداف المنصوص عليها في هذا النظام'),('خمسة من الأعضاء الأساسيين في الهيئة'),('دود ما ينص عليه التنظيم وما يقرره المجلس'),('دون إخلال باختصاصات صندوق التنمية الوطني'),('ر المعلومات الإحصائية التي تصدرها الهيئة'),('رئيس مجلس إدارة الهيئة العامة للطرق'),('رج المملكة يكون رسم الشهر الإضافي مضاعفا'),('رسالية مواد كيميائية حال تقديم إذن فسحها'),('س إدارة يعين رئيسه بقرار من مجلس الوزراء'),('سم مضاعف عما يحصل إذا كانوا داخل المملكة'),('سه أو إلى لجانه أو إلى من يراه من أعضائه'),('سوبو الهيئة بالمحافظة على سرية المعلومات'),('شح الرئيس الأعضاء المشار إليهم في الفقرة'),('صدر اللجنة الآليات اللازمة لتطبيق النظام'),('ط تنظيميا بالهيئة العامة للتطوير الدفاعي'),('ع الأثرية في منتزه عين نجم وفقا لتنظيمها'),('ع صاحب المعاش المفقود وفق الأحكام الآتية'),('عدم الوفاء بها من مساس بأداء مناسك الحج'),('عضوية مجلس الهيئة المشار إليه في المادة'),('على وضع وتنفيذ استراتيجيات العمل التطوعي'),('عية متابعة الدعوى المشار إليها في الفقرة'),('فر مدة لا تزيد على خمس سنوات أو بهما معا'),('فقا لأحكام اتفاق لاهاي ولائحته التنفيذية'),('في ذلك الاستثمار في تملك العقار وتأجيره'),('ق التقنية بالتنسيق مع الجهات ذات العلاقة'),('قتراح من مجلس الشؤون الاقتصادية والتنمية'),('قيادة المركبة في الطرق برخصة سير منتهية'),('ل أو أكثر من نطاق تطبيق بعض أحكام الفصول'),('لأعمال والخدمات التي تقدمها وفقا للتنظيم'),('لا يتعارض مع الأنظمة والقرارات ذات الصلة'),('لعام بشكل دوري وفق معايير يعتمدها المجلس'),('للأنظمة والصلاحيات التي يفوضه بها المجلس'),('لمدة ثلاث سنوات قابلة للتجديد مرة واحدة'),('لمرخصة بموجب أحكام نظام الإيجار التمويلي'),('لمستثناة التي تكون جهة الإدارة طرفا فيها'),('لها إلى جهة الضبط وفقا لما ورد في المادة'),('م خلال ستين يوما من إبلاغه بقرار العقوبة'),('م والضوابط اللازمة لما ورد في هذه المادة'),('م وضعها بالاتفاق مع صندوق التنمية الوطني'),('مؤداة وما ترتب عليها من مساس بفريضة الحج'),('مالية المتعلقة بمخالفات أحكام هذا النظام'),('مة أو تحول منسوبيها من نظام إلى نظام آخر'),('ملكة على مراحل وفق ما تقرره وزارة الطاقة'),('ممثل من بنك التصدير والاستيراد السعودي'),('من رئيس مجلس إدارة صندوق التنمية الوطني'),('من مجلس الوزراء بناء على ترشيح من الرئيس'),('منتظما في سداد رسوم العضوية المقررة لآخر'),('مويل وكل عضو مجلس مديريها أو من في حكمهم'),('ن تقديم بيان جمركي تفصيلي في مركز الدخول'),('نشرات والتقارير الإحصائية للمسوح والبحوث'),('نقله من بلد إلى آخر في الداخل أو الخارج'),('هاء من إعادة هيكلة قطاع الكهرباء وتخصيصه'),('و من غيرهم للقيام بما يكلفها به من مهمات'),('و موافقة للاستثمار في مدينة صناعية محددة'),('والبروتوكولات والعقود بعد موافقة المجلس'),('وة من رئيسه أربع مرات على الأقل في السنة'),('وزارة الصناعة والثروة المعدنية'),('وضوابط وإجراءات يقرها مجلس إدارة الصندوق'),('ولة بأي من نظامي التقاعد المدني والعسكري'),('ويبدأ العمل بهذا البند من تاريخ'),('ويصدر بتعيينهم أمر من رئيس مجلس الوزراء'),('ى أعمال الهيئة الفنية والإدارية والمالية'),('ي المركز الوطني لتنمية القطاع غير الربحي'),('يئة ومساعد الرئيس معاونة الرئيس في حضوره'),('ية التي تمارس نشاط بيع المواد الكيميائية'),('يتجاوز العقوبات المنصوص عليها في المادة'),('ير مباشر إلا بعد الحصول على موافقة البنك'),('يرتبط المركز تنظيميا بوزير الصحة'),('يريها وأعضاء مجلس مديريها أو من في حكمهم'),('يس أو من ينيبه سواء كان حضوريا أو عن بعد'),('يص وتصنيفاتها التي تدخل في اختصاص الهيئة')), t(b) AS MATERIALIZED (SELECT regexp_replace(regexp_replace(translate(normalize(content, NFC), '“”„«»', '"""""'), '[\u064B-\u0652\u0640]', '', 'g'), '\s+', ' ', 'g') FROM legal_articles UNION ALL SELECT regexp_replace(regexp_replace(translate(normalize(body, NFC), '“”„«»', '"""""'), '[\u064B-\u0652\u0640]', '', 'g'), '\s+', ' ', 'g') FROM unit_version) SELECT md5(string_agg(key, '|' ORDER BY key COLLATE "C")) keys_fp, count(*) n, string_agg(CASE WHEN NOT EXISTS (SELECT 1 FROM t WHERE strpos(t.b, k.key) > 0) THEN md5(key) END, ',') missing FROM k